    def test_receive_appends_and_prints(self):
        self.shop()
        self.assertEqual(self.ok("receive", "2024-04-01", "ef-310", "7", " boxed "), "2024-04-01 EF-310 +7 boxed\n")
        self.assertEqual(self.read("movements.txt"), (MOVEMENTS + "2024-04-01 EF-310 +7 boxed\n").encode())

    def test_ship_without_note(self):
        self.shop()
        self.assertEqual(self.ok("ship", "2024-04-01", "AB-100", "2"), "2024-04-01 AB-100 -2\n")
        self.assertEqual(self.ok("ship", "2024-04-02", "AB-100", "1", "  "), "2024-04-02 AB-100 -1\n")
        self.assertTrue(self.read("movements.txt").endswith(b"2024-04-01 AB-100 -2\n2024-04-02 AB-100 -1\n"))

    def test_newline_fixup_and_file_created(self):
        self.shop(movements="2024-03-01 AB-100 +20")
